import csv, json, collections
from datetime import datetime, timezone, timedelta
def rd(p): return list(csv.DictReader(open(p)))
def T(s): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
plan={r['run_id']:r for r in rd('plan.csv')}
lm={r['run_id']:r for r in rd('launch_log.csv')}
E={r['run_id']:float(r['pass_rate']) for r in rd('eval_results.csv')}
R={r['run_id']:T(r['finished_at']) for r in rd('runtime.csv')}
RL={r['run_id']:r for r in rd('retention_log.csv')}
pol=json.load(open('retention_policy.json'))['versions']
def floor(t):
    for v in pol:
        if T(v['from'])<=t<T(v['to']): return v['floor']
rec={}
for i in range(4):
    for r in rd(f'recovered/shard_0{i}.csv'): rec[r['run_id']]=round(float(r['pass_rate_pct'])/100,4)
w0=T('2026-06-27T00:00:00Z'); w1=T('2026-07-03T12:00:00Z')
L=set(lm)
outage={k for k in L if lm[k]['worker'] in('w03','w07') and w0<=T(lm[k]['started_at'])<w1}
miss=L-set(E)
# 1. recovered outage runs without retlog entry: below floor(finish)?
bad=[(k,rec[k],floor(R[k]),R[k]) for k in miss if k in rec and k not in RL and rec[k]<floor(R[k])]
print('recovered, not in retlog, below floor@finish:',len(bad)); [print(' ',b) for b in bad]
print('recovered outage noret total',sum(1 for k in miss if k in rec and k not in RL))
print('recovered outage noret near floor (<floor+0.03):',sorted((rec[k],floor(R[k])) for k in miss if k in rec and k not in RL and rec[k]<floor(R[k])+0.03))
# 2. digest residuals
dig={r['date']:(int(r['n_runs']),float(r['sum_pass_rate'])) for r in rd('daily_digest.csv')}
byday=collections.defaultdict(list)
for k in L: byday[R[k].strftime('%Y-%m-%d')].append(k)
val={**E,**{k:v for k,v in rec.items() if k in L}}
for d in sorted(dig):
    ks=byday[d]; known=sum(val[k] for k in ks if k in val); free=[k for k in ks if k not in val]
    resid=round(dig[d][1]-known,4)
    info=[(k,plan[k]['suite'],'out' if k in outage else '', RL[k]['reason'][:8] if k in RL else '-', floor(R[k])) for k in free]
    print(d,'resid %.4f'%resid,'free',len(free), 'mean %.4f'%(resid/len(free)) if free else '', info if len(free)<=3 else '')
